compile.workshop:
settings
{
	main
	{
		Description: "Your weapon has a chance to break when you fire it. Kill someone who still has their weapon to get it back! Made by Zezombye | credit to NyaWalking for the weapon removal"
	}
	modes
	{
		disabled Assault
		{
			Competitive Rules: On
			Limit Roles: 2 Of Each Role Per Team
		}
		disabled Control
		{
			Competitive Rules: On
			Limit Roles: 2 Of Each Role Per Team
		}
		Escort
		{
			Competitive Rules: On
			Limit Roles: 2 Of Each Role Per Team
		}
		Hybrid
		{
			Competitive Rules: On
			Limit Roles: 2 Of Each Role Per Team
		}
	}
	heroes
	{
		General
		{
			disabled heroes
			{
				Ashe
				Bastion
				D.Va
				Doomfist
				Echo
				Moira
				Reinhardt
				Wrecking Ball
				Zenyatta
			}
		}
	}
}

variables {
    global:
        0: baseChance
        1: hanzoChance
        2: sigmaChance
        3: brigChance
        4: mercyChance
    player:
        0: ammo0
        1: ammo1
        2: hero
        3: isWeaponBroken
}

rule ("Initialize global variables") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(baseChance, Workshop Setting Real(Custom String("　"), Custom String("Base chance to break 1󠀯󠀨x * max ammo󠀩"), 4, 0.5, 10, 0));
        Set Global Variable(hanzoChance, Workshop Setting Real(Custom String("　"), Custom String("Hanzo chance to break 󠀨each arrow fired󠀩 1󠀯x"), 20, 1, 50, 1));
        Set Global Variable(sigmaChance, Workshop Setting Real(Custom String("　"), Custom String("Sigma chance to break 󠀨each ball fired󠀩 1󠀯x"), 30, 1, 50, 1));
        Set Global Variable(brigChance, Workshop Setting Real(Custom String("　"), Custom String("Brigitte chance to break 󠀨each hit󠀩 1󠀯x"), 20, 1, 50, 2));
        Set Global Variable(mercyChance, Workshop Setting Real(Custom String("　"), Custom String("Mercy chance to break 󠀨each tick󠀩 1󠀯x"), 1000, 100, 4000, 2));
    }
}

rule ("magz why is assemble hero time 30 seconds") {
    event {
        Ongoing - Global;
    }
    conditions {
        Is Assembling Heroes == True;
    }
    actions {
        Set Match Time(10);
    }
}

rule ("changing hero resets weapon") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        (Event Player).hero != Hero Of(Event Player);
    }
    actions {
        Wait(0.016, Ignore Condition);
        Set Player Variable(Event Player, isWeaponBroken, False);
        Set Weapon(Event Player, 1);
        Set Player Variable(Event Player, hero, Hero Of(Event Player));
        Set Player Variable(Event Player, ammo0, Ammo(Event Player, 0));
        Set Player Variable(Event Player, ammo1, Ammo(Event Player, 1));
        Loop If Condition Is True;
    }
}

rule ("reset weapon broken") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Has Spawned(Event Player) == True;
        Is Alive(Event Player) == True;
    }
    actions {
        Set Player Variable(Event Player, isWeaponBroken, False);
        Set Weapon(Event Player, 1);
    }
}

rule ("kill someone who has weapon") {
    event {
        Player Dealt Final Blow;
        All;
        All;
    }
    conditions {
        (Attacker).isWeaponBroken != False;
        (Victim).isWeaponBroken == False;
    }
    actions {
        Set Player Variable(Attacker, isWeaponBroken, False);
        Set Weapon(Attacker, 1);
        Big Message(Attacker, Custom String("Stole {0}'s weapon", Victim));
    }
}

rule ("keep weapon broken") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        (Event Player).isWeaponBroken != False;
        Weapon(Event Player) != 1.1;
    }
    actions {
        Set Weapon(Event Player, 1.1);
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("weapon broke") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        (Event Player).isWeaponBroken != False;
    }
    actions {
        Big Message(Event Player, Custom String("Your weapon broke!"));
    }
}

rule ("detect ammo change for clip 0, and potentially break weapon") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Hero Of(Event Player) == (Event Player).hero;
        Array Contains(Array(Hero(Hanzo), Hero(Brigitte)), Hero Of(Event Player)) == False;
        Or(Compare(Weapon(Event Player), ==, 2), Not(Array Contains(Array(Hero(Torbjörn), Hero(Mercy)), Hero Of(Event Player)))) == True;
        (Event Player).ammo0 != Ammo(Event Player, 0);
        (Event Player).isWeaponBroken == False;
    }
    actions {
        If(Compare((Event Player).ammo0, >, Ammo(Event Player, 0)));
            If(Compare(Random Integer(0, Multiply(Max Ammo(Event Player, 0), Global.baseChance)), <, Subtract((Event Player).ammo0, Ammo(Event Player, 0))));
                Set Player Variable(Event Player, isWeaponBroken, True);
            End;
        End;
        Set Player Variable(Event Player, ammo0, Ammo(Event Player, 0));
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("detect ammo change for clip 1, and potentially break weapon") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Hero Of(Event Player) == (Event Player).hero;
        Array Contains(Array(Hero(Hanzo), Hero(Brigitte)), Hero Of(Event Player)) == False;
        Or(Compare(Weapon(Event Player), ==, 2), Not(Array Contains(Array(Hero(Torbjörn), Hero(Mercy)), Hero Of(Event Player)))) == True;
        (Event Player).ammo1 != Ammo(Event Player, 1);
        (Event Player).isWeaponBroken == False;
    }
    actions {
        If(Compare((Event Player).ammo1, >, Ammo(Event Player, 1)));
            If(Compare(Random Integer(0, Multiply(Max Ammo(Event Player, 1), Global.baseChance)), <, Subtract((Event Player).ammo1, Ammo(Event Player, 1))));
                Set Player Variable(Event Player, isWeaponBroken, True);
            End;
        End;
        Set Player Variable(Event Player, ammo1, Ammo(Event Player, 1));
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("hanzo break") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Hero Of(Event Player) == Hero(Hanzo);
        Is Firing Primary(Event Player) == True;
        (Event Player).isWeaponBroken == False;
    }
    actions {
        Wait Until(Not(Is Firing Primary(Event Player)), 999);
        Abort If(Or(Compare(Hero Of(Event Player), !=, Hero(Hanzo)), (Event Player).isWeaponBroken));
        If(Compare(Random Integer(0, Global.hanzoChance), ==, 0));
            Set Player Variable(Event Player, isWeaponBroken, True);
        End;
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("sigma break") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Hero Of(Event Player) == Hero(Sigma);
        Is Firing Primary(Event Player) == True;
        (Event Player).isWeaponBroken == False;
    }
    actions {
        Wait Until(Not(Is Firing Primary(Event Player)), 999);
        Abort If(Or(Compare(Hero Of(Event Player), !=, Hero(Sigma)), (Event Player).isWeaponBroken));
        If(Compare(Random Integer(0, Global.sigmaChance), ==, 0));
            Set Player Variable(Event Player, isWeaponBroken, True);
        End;
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

rule ("torb or brig deal dmg") {
    event {
        Player Dealt Damage;
        All;
        All;
    }
    conditions {
        Or(Compare(Hero Of(Event Player), ==, Hero(Brigitte)), And(Compare(Hero Of(Event Player), ==, Hero(Torbjörn)), Compare(Weapon(Event Player), ==, 2))) == True;
        "@Condition eventAbility == Button.PRIMARY_FIRE"
        (Event Player).isWeaponBroken == False;
    }
    actions {
        Create HUD Text(All Players(All Teams), Event Ability, Custom String("                                                                                                                             {0}", Custom String("                                             ")), Null, Left, -9999, Color(Orange), Null, Null, Visible To and String, Default Visibility);
        If(Compare(Random Integer(0, Global.brigChance), ==, 0));
            Set Player Variable(Event Player, isWeaponBroken, True);
    }
}

rule ("mercy deal healing") {
    event {
        Ongoing - Each Player;
        All;
        All;
    }
    conditions {
        Hero Of(Event Player) == Hero(Mercy);
        Weapon(Event Player) == 1;
        Or(Is Firing Primary(Event Player), Is Firing Secondary(Event Player)) == True;
        (Event Player).isWeaponBroken == False;
    }
    actions {
        If(Compare(Random Integer(0, Global.mercyChance), ==, 0));
            Set Player Variable(Event Player, isWeaponBroken, True);
        End;
        Wait(0.016, Ignore Condition);
        Loop If Condition Is True;
    }
}

